// ===== p194 : quatre boucles de maloya jouées par l’auteur dans Kontakt =====
// Rythmes de la librairie « Maloya Roots Percussions » (Wayo Audio), mixés ensemble en une prise par formation :
// kabaré, kasse, malbar binaire, maligasse, moring, pleure, roule, valse. Boucles de 12, 16 ou 24 s, mono 64 kb/s.
// Licence Wayo : les sons ne sont pas redistribuables isolément ; ici ce sont des mixages complets, intégrés au jeu.
Object.assign(SON193,{"boucle_kabare": "", "boucle_kasse": "", "boucle_malbar": "", "boucle_maligasse": "", "boucle_moring": "", "boucle_pleure": "", "boucle_roule": "", "boucle_valse": "", "boucle_intro_kabar": "", "boucle_intro_jeu": ""});
const BCL194={intro_jeu:98,intro_kabar:16,kabare:12,kasse:16,malbar:16,maligasse:12,moring:12,pleure:12,roule:24,valse:12};
function boucle194(ctx,dest,nom,v,une){try{const B=sons193(ctx),b=B&&B['boucle_'+nom];if(!b)return null;const s=ctx.createBufferSource();s.buffer=b;const L=Math.min(b.duration,BCL194[nom]||b.duration);
 if(!une){s.loop=true;s.loopStart=0;s.loopEnd=L}
 const g=ctx.createGain(),t=ctx.currentTime;g.gain.value=0;g.gain.setTargetAtTime(v,t,.4);if(une)g.gain.setTargetAtTime(0,t+L-2.5,.8);
 const sp=ctx.createGain(),F=ctx.createBiquadFilter();F.type='lowpass';F.frequency.value=18000;F.Q.value=.5;s.connect(g);g.connect(sp);sp.connect(F);F.connect(dest);s.start(t,0,une?L:undefined);
 return {nom,sp,F,ctx,stop(){try{g.gain.setTargetAtTime(0,ctx.currentTime,.5);s.stop(ctx.currentTime+2.5)}catch(e){}}}}catch(e){return null}}
// dans l'île : le kabar (kabaré, maligasse ou kasse), le moringue (moring), les fêtes tamoules (malbar),
// la fuite des marrons (roule), les bals (valse) ; le deuil joue « pleure » une fois
try{if(typeof PRE72!=='undefined'&&typeof SONCH!=='undefined'){let cur=null,curK='';
 const def=(k,choix)=>{const o={d:3.6,f:()=>{const c=typeof sndPret==='function'&&sndPret();if(!c)return;
   if(cur&&curK===k){o.d=3600;return}if(cur){cur.stop();cur=null}const nom=choix();
   // le kabar d'un camp s'ouvre sur les 15 secondes composées par l’auteur dans l'Atelier, puis la boucle prend le relais
   if(k==='bclKabar'&&sons193(c)['boucle_intro_kabar']){const bus=c.createGain(),F=c.createBiquadFilter();F.type='lowpass';F.frequency.value=18000;bus.connect(F);F.connect(SND.out);
    const intro=boucle194(c,bus,'intro_kabar',1.1,1);let suite=null;const h=setTimeout(()=>{suite=boucle194(c,bus,nom,.6)},14800);
    cur={nom,sp:bus,F,ctx:c,stop(){clearTimeout(h);try{intro&&intro.stop()}catch(e){}try{suite&&suite.stop()}catch(e){}}}}
   else cur=boucle194(c,SND.out,nom,.6);window.CUR194=cur;
   if(cur){curK=k;o.d=3600}else{o.d=3.6;if(PRE72.maloya68)PRE72.maloya68.f()}}};PRE72[k]=o};
 const KB=['kabare','maligasse','kasse'];
 // le kabar selon l'époque : avant 1850, la « danse des Noirs » et le premier shéga, sans triangle (il n'arrive qu'au milieu du XIXᵉ) ;
 // de 1850 à 1920, le séga des origines avec son triangle ; à partir de 1921, le maloya, tous les ensembles
 def('bclKabar',()=>{const y=S&&S.year||1700,L=y<1850?['maligasse','pleure']:y<1921?['kabare','kasse','maligasse']:KB;return L[Math.floor(Math.random()*L.length)]});def('bclMoring',()=>'moring');def('bclMalbar',()=>'malbar');def('bclRoule',()=>'roule');def('bclValse',()=>'valse');
 const z0=PRE72.zion;PRE72.bclPleure={d:12,f:()=>{const c=typeof sndPret==='function'&&sndPret();if(!(c&&boucle194(c,SND.out,'pleure',.55,1))&&z0)z0.f()}};
 SONCH.kabar='bclKabar';SONCH.jDuel='bclMoring';SONCH.malbar='bclMalbar';SONCH.roule='bclRoule';SONCH.valse='bclValse';SONCH.deces='bclPleure';
 setInterval(()=>{try{if(cur&&SONCH[SND.ambK]!==curK){const fin=curK==='bclKabar';cur.stop();cur=null;curK='';if(fin&&typeof bout205==='function')setTimeout(()=>bout205('kasse',2,.55),350)}}catch(e){}},300);
 // la musique vient du camp : on l'entend pleine dedans, étouffée et portée par les rafales quand la vue s'éloigne,
 // et l'ambiance (mer, rivière, vent) s'efface un peu devant elle
 setInterval(()=>{try{const m=cur;let duck=0,K194=null;if(m&&m.sp){const c=m.ctx,t=c.currentTime;let near=1,zf=1;
   if(typeof camT!=='undefined'){const cc=(typeof camps==='function'&&camps()[0])||null;if(cc){const d=Math.hypot(camT.x-cc.x,camT.z-cc.z);K194=typeof courbe200==='function'?courbe200('kabar',d):null;near=K194?K194.v:Math.max(0,Math.min(1,1-(d-3)/22))}
    if(typeof dist!=='undefined')zf=Math.max(.35,Math.min(1,1-(dist-10)/80))}
   const raf=typeof RAF72!=='undefined'?RAF72.v:1,porte=1+(1-near)*(Math.min(1.8,raf)-1)*.6,lv=Math.max(.03,(K194?near:(.2+.8*near))*zf*porte);
   m.sp.gain.setTargetAtTime(lv,t,.35);m.F.frequency.setTargetAtTime(K194?Math.max(300,K194.hz*(.5+.5*zf)):900+17000*Math.pow(near*zf,2),t,.4);duck=near*zf}
  // l'ambiance entre doucement : au début d'une partie, et à chaque grand changement de lieu (on ouvre un lieu, un camp, la vue personnage, ou la vue saute loin)
  {const E=SND.ambE=SND.ambE||{v:0,t:performance.now(),x:null,z:null,k:''};const now=performance.now();
   if(typeof camT!=='undefined'){if(E.x!=null&&Math.hypot(camT.x-E.x,camT.z-E.z)>6)E.v=Math.min(E.v,.15);E.x=camT.x;E.z=camT.z}
   const cle=(typeof lieu!=='undefined'&&lieu?'l'+lieu.i:'')+(typeof VP!=='undefined'&&VP?'v':'')+(typeof CV!=='undefined'&&CV&&CV.on?'c':'')+(typeof S!=='undefined'&&S?'s':'');
   if(cle!==E.k){E.k=cle;E.v=Math.min(E.v,.15)}const dtA=Math.min(1000,now-E.t);E.v=Math.min(1,E.v+dtA/12000);E.t=now;
   // une annonce casse l'ambiance de 54 %, qui revient ensuite progressivement
   const md=document.getElementById('modal'),ann=!!(md&&!md.hidden);if(E.a==null)E.a=1;if(ann)E.a=.46;else E.a=Math.min(1,E.a+dtA/3500)}
  if(SND.ambBus&&SND.ctx)SND.ambBus.gain.setTargetAtTime((1/6)*(1-.45*duck)*(SND.ambE?SND.ambE.v*(SND.ambE.a==null?1:SND.ambE.a):1),SND.ctx.currentTime,.6)}catch(e){}},250);
 // un événement qui parle de fête tamoule, de fuite marronne ou de bal installe sa musique pendant 16 s
 const EVM=[[/malbar|tamoul|tamij|marche sur le feu|pandal|kavadi|pongal|kovil/,'malbar'],[/fuir|fuite|évad|s'enfui|chasseurs de noirs|détachement/,'roule'],[/\bbal\b|valse|quadrille|polka|soirée chez|réception chez/,'valse']];
 SND.m194=null;SND.m194J=0;
 if(typeof momentCourant==='function'){const mc=momentCourant;momentCourant=function(){try{if(SND.m194&&performance.now()<SND.m194J&&!(SND.jeu&&window.BTUON)&&!(typeof CINE!=='undefined'&&CINE))return SND.m194}catch(e){}return mc.apply(this,arguments)}}
 if(typeof modal==='function'){const md=modal;modal=function(){try{if(S&&S.evq&&S.evq.length){const e=EV[S.evq[0]]||{},tx=((e.t||'')+' '+(typeof e.b==='string'?e.b:'')).toLowerCase();
   if(!/kabar|maloya|moringue/.test(tx))for(const [re,m] of EVM)if(re.test(tx)){SND.m194=m;SND.m194J=performance.now()+16000;break}}}catch(e){}return md.apply(this,arguments)}}
}}catch(e){}
try{CRED144.push(["Boucles de maloya (kabaré, kasse, malbar, maligasse, moring, pleure, roule, valse) : rythmes de la librairie « Maloya Roots Percussions », Wayo Audio, joués et mixés pour le jeu","Wayo Audio"])}catch(e){}

// ===== le cyclone s'annonce : la saison d'avant commence au beau fixe, sans nuage ni vent ; il approche sur la fin
// (pendant le dernier bras s'il n'y en a que 2, sur les 2 derniers s'il y en a plus de 5) et frappe la saison suivante =====
function approche194(){try{if(!S||S.fin||!S.cyc)return 0;const n=S.cyc.in;if(n<=0)return 1;if(n>1)return 0;
 const n0=typeof brasMax==='function'?brasMax():3,k=n0<=2?1:n0<=5?1.5:2,r=Math.max(0,S.bras||0);
 return Math.max(0,Math.min(1,(k+1-r)/(k+1)))}catch(e){return 0}}
